<?php
namespace App\Http\Controllers;
use App\Models\{AttendanceSession,SchoolClass};use App\Services\AttendanceService;use Illuminate\Http\Request;
class AttendanceController extends Controller {public function show(Request $request,SchoolClass $class){$this->authorize('view',$class);$session=$class->sessions()->firstOrCreate(['attendance_date'=>today(config('app.timezone'))],['school_id'=>$class->school_id,'teacher_id'=>$request->user()->teacher?->id]);return view('teacher.attendance',compact('class','session'));}public function save(Request $request,SchoolClass $class,AttendanceService $service){$request->validate(['records'=>'required|array','records.*.student_id'=>'required|integer','records.*.status'=>'required|in:present,absent,late']);$service->save($request->user(),$class,$request->input('records'));return back()->with('success','Attendance saved.');}public function submit(Request $request,AttendanceSession $session,AttendanceService $service){$service->submit($request->user(),$session);return back()->with('success','Attendance submitted; absent-parent SMS records have been queued or simulated.');}}
